using Backend.Exceptions;using Microsoft.Extensions.Logging;using Polly;using Polly.Retry;namespace Backend.Policies;public static class PollyPolicies{    public static ResiliencePipeline CrearPipelineSerializacion(ILogger logger)    {        return new ResiliencePipelineBuilder()            .AddRetry(new RetryStrategyOptions            {                ShouldHandle = new PredicateBuilder().Handle<RetryableException>(),                MaxRetryAttempts = 3,                BackoffType = DelayBackoffType.Exponential,                Delay = TimeSpan.FromMilliseconds(200),                OnRetry = args =>                {                    logger.LogWarning(                        "Reintento {RetryAttempt}/3 tras conflicto de serialización (40001). " +                        "Siguiente intento en {Delay}ms. Excepción: {Message}",                        args.AttemptNumber,                        args.RetryDelay.TotalMilliseconds,                        args.Outcome.Exception?.Message ?? "desconocida");                    return ValueTask.CompletedTask;                }            })            .Build();    }}